function bestRotationSum(nums: number[]): number {
  const n = nums.length;
  let best = -Infinity;
  for (let k = 0; k < n; k++) {
    let f = 0;
    // after rotating right by k, index i holds nums[(i - k + n) % n]
    for (let i = 0; i < n; i++) f += i * nums[(i - k + n) % n];
    best = Math.max(best, f);
  }
  return best;
}

