function bestRotationSum(nums: number[]): number {
  const n = nums.length;
  let total = 0, f = 0;
  for (let i = 0; i < n; i++) {
    total += nums[i];
    f += i * nums[i];
  }
  let best = f;
  for (let k = 1; k < n; k++) {
    f += total - n * nums[n - k];
    best = Math.max(best, f);
  }
  return best;
}

